-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('noticing-the-seasons-change', 'Noticing the Seasons Change', 'For anyone who wants to feel more in step with the time of year. Each day is one small way to notice what is changing outside, enjoy what this season brings and let your home and habits shift gently with it.', 'Mindfulness', 365, array['Mindfulness', 'Self-Care', 'Habits']::text[], 1, '2026-11-05T17:00:00+00:00'::timestamptz),
  ('living-well-with-roommates', 'Living Well with Roommates', 'For anyone sharing a home with roommates, housemates or friends. Each day is one small way to talk things through kindly, share the space fairly, keep your own corner restful and enjoy the people you live with.', 'Relationships', 365, array['Relationships', 'Communication', 'Boundaries']::text[], 1, '2026-11-05T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('noticing-the-seasons-change', 'living-well-with-roommates');

